function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  background("#e4e0c6");
  translate(-width / 2, -height / 2);
  stroke(0, 255);
  strokeWeight(2);
  for (let i = 0; i < 12; i++) {
    for (let j = 0; j < 5; j++) {
      fill("#e08a72", 255);
      brush.fillBleed(0.5);
      brush.circle(0 + i * 30, 0 + j * 30, 10);
    }
  }
}
